{
  "gateway": "meta_native_action",
  "mode": "direct",
  "description": "Run a Meta Graph Marketing API action by name for deferred or advanced operations. Prefer named tools such as create campaign, fetch ad account, upload media, and get insights when they are available.",
  "inputSchema": {
    "type": "object",
    "properties": {
      "action": {
        "type": "string",
        "minLength": 1,
        "description": "Meta Graph Marketing API action/tool name, LIST_ACTIONS, or DESCRIBE_ACTION. Use search=\"assigned users\" or search=\"business user\" to discover access-management actions."
      },
      "target_action": {
        "type": "string",
        "description": "Action to inspect when action=DESCRIBE_ACTION."
      },
      "search": {
        "type": "string",
        "description": "LIST_ACTIONS case-insensitive action, alias, category, endpoint, or documentation filter."
      },
      "category": {
        "type": "string",
        "description": "LIST_ACTIONS category filter."
      },
      "read_only": {
        "type": "boolean",
        "description": "LIST_ACTIONS read/write filter."
      },
      "limit": {
        "type": "integer",
        "minimum": 1,
        "maximum": 500,
        "description": "LIST_ACTIONS page size; defaults to 50."
      },
      "offset": {
        "type": "integer",
        "minimum": 0,
        "description": "LIST_ACTIONS zero-based offset."
      },
      "connection_id": {
        "type": "string",
        "format": "uuid",
        "description": "Optional Meta OAuth connection ID."
      },
      "ad_account_id": {
        "type": "string",
        "description": "Meta ad account ID; 123 or act_123."
      },
      "account_id": {
        "type": "string",
        "description": "Alias for ad_account_id."
      },
      "business_id": {
        "type": "string",
        "description": "Meta Business ID."
      },
      "page_id": {
        "type": "string",
        "description": "Meta Page ID; used to resolve a Page Access Token for page and lead-gen actions."
      },
      "path_params": {
        "type": "object",
        "additionalProperties": {},
        "description": "Templated Graph path params."
      },
      "params": {
        "$ref": "#/properties/path_params",
        "description": "Native Meta params."
      },
      "query": {
        "$ref": "#/properties/path_params",
        "description": "Explicit query params."
      },
      "payload": {
        "$ref": "#/properties/path_params",
        "description": "Native Meta body exactly as documented."
      },
      "campaign": {
        "$ref": "#/properties/path_params",
        "description": "Sibling campaign context for preflight only."
      },
      "adset": {
        "$ref": "#/properties/path_params",
        "description": "Sibling ad set context for preflight only."
      },
      "creative": {
        "$ref": "#/properties/path_params",
        "description": "Sibling creative context for preflight only."
      },
      "ad": {
        "$ref": "#/properties/path_params",
        "description": "Sibling ad context for preflight only."
      },
      "assets": {
        "$ref": "#/properties/path_params",
        "description": "Resolved asset facts for preflight only."
      },
      "context": {
        "$ref": "#/properties/path_params",
        "description": "Workspace/account facts for preflight only."
      },
      "aggregate_pages": {
        "type": "boolean",
        "default": false,
        "description": "Follow paging.next when true."
      },
      "max_pages": {
        "type": "integer",
        "minimum": 1,
        "maximum": 100,
        "default": 25,
        "description": "Page cap for aggregate_pages."
      },
      "confirmed": {
        "type": "boolean",
        "default": false,
        "description": "Required for destructive live calls."
      },
      "dry_run": {
        "type": "boolean",
        "default": true,
        "description": "Writes preview by default; read actions ignore it."
      },
      "skip_preflight": {
        "type": "boolean",
        "default": false,
        "description": "Bypass curated write preflight."
      },
      "override_preflight": {
        "type": "boolean",
        "default": false,
        "description": "Alias for skip_preflight."
      },
      "idempotency_key": {
        "type": "string",
        "description": "Idempotency key for writes."
      },
      "result_fields": {
        "type": "array",
        "items": {
          "type": "string"
        },
        "description": "Project MCP result records to these fields."
      },
      "fields": {
        "anyOf": [
          {
            "type": "string"
          },
          {
            "type": "array",
            "items": {
              "type": "string"
            }
          }
        ],
        "description": "Native Meta Graph fields selector or Insights metrics. Use result_fields for MCP response projection."
      },
      "batch": {
        "description": "Graph API batch array for meta_batch_create/meta_graph_batch_create. Prefer the specific meta_batch_create tool when available."
      },
      "adbatch": {
        "$ref": "#/properties/batch",
        "description": "Async Marketing API batch array for meta_async_batch_create/meta_ad_account_id_async_batch_requests_create."
      },
      "include_headers": {
        "$ref": "#/properties/batch",
        "description": "Optional Graph batch include_headers flag."
      },
      "report_run_id": {
        "type": "string",
        "description": "Meta AdReportRun ID for polling or fetching async report results."
      },
      "max_items": {
        "type": "integer",
        "minimum": 1,
        "maximum": 10000,
        "description": "Cap returned arrays in the MCP result."
      },
      "compact": {
        "type": "boolean",
        "default": false,
        "description": "Remove null, empty string, and empty object values from the MCP result."
      }
    },
    "required": [
      "action"
    ],
    "additionalProperties": true,
    "$schema": "http://json-schema.org/draft-07/schema#"
  }
}
